pe\": \"text\"}, {\"bbox\": [{\"coord\": [33, 329, 864, 488], \"page_id\": 155}], \"content\": \"<table><tr><td>TRBU SMITH212J</td><td>ISSDUE000</td><td>R</td><td>1</td></tr><tr><td>JOHN SMITH</td><td></td><td></td><td></td></tr><tr><td>212 MAIN ST</td><td></td><td></td><td></td></tr><tr><td>FORESTVILLE MD 20747</td><td></td><td></td><td></td></tr></table>\", \"description\": null, \"id\": 4, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [33, 508, 1386, 579], \"page_id\": 155}], \"content\": \"When that number reads ISSDUE000, you have received your last issue unless you renew. You should receive your renewal notice around the same time that you receive the issue with ISSDUE000 on the top line.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [32, 605, 1386, 705], \"page_id\": 155}], \"content\": \"To be sure that your service continues without interruption, please return your renewal notice promptly. If your subscription service is discontinued, simply send your mailing label from any issue to the Superintendent of Documents, Washington, DC 20402-9372 with the proper remittance, and your service will be reinstated.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [33, 735, 1386, 804], \"page_id\": 155}], \"content\": \"To change your address . . . please SEND YOUR MAILING LABEL, along with your new address, to the Superintendent of Documents, Attn: Chief, Mail List Branch, Mail Stop: SSOM, Washington, DC 20402-9373.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [33, 833, 1386, 899], \"page_id\": 155}], \"content\": \"To inquire about your subscription service ... please SEND YOUR MAILING LABEL, along with your correspondence, to the Superintendent of Documents, Attn: Chief, Mail List Branch, Mail Stop: SSOM, Washington, DC 20402-9375.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [32, 967, 226, 994], \"page_id\": 155}], \"content\": \"New Subscribers\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [33, 998, 834, 1031], \"page_id\": 155}], \"content\": \"To order a new subscription please use the order form provided below.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [358, 1126, 1118, 1164], \"page_id\": 155}], \"content\": \"Superintendent of Documents Subscriptions Order Form\", \"description\": null, \"id\": 11, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [35, 1164, 159, 1190], \"page_id\": 155}], \"content\": \"Order Processing Code\", \"description\": null, \"id\": 12, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [36, 1193, 141, 1217], \"page_id\": 155}], \"content\": \"*6735\", \"description\": null, \"id\": 13, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [35, 1221, 176, 1261], \"page_id\": 155}], \"content\": \"YES\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [172, 1228, 781, 1263], \"page_id\": 155}], \"content\": \", please send me the following indicated subscriptions:\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [982, 1171, 1250, 1232], \"page_id\": 155}], \"content\": \"Charge your order. It's easy!\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1270, 1160, 1436, 1224], \"page_id\": 155}], \"content\": null, \"description\": null, \"id\": 17, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [969, 1228, 1435, 1255], \"page_id\": 155}], \"content\": \"To fax your orders and inquiries\\u2014(202) 275-0019\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [207, 1290, 1189, 1391], \"page_id\": 155}], \"content\": \"subscriptions of TREASURY BULLETIN, TRBU, for $27.00 per year.\\nsubscriptions of DAILY TREASURY STATEMENT, DTS, for $174.00 per year.\\nsubscriptions of MONTHLY TREASURY STATEMENT, MTSRO, for $22.00 per year.\", \"description\": null,