bbox\": [{\"coord\": [112, 577, 957, 671], \"page_id\": 2}], \"content\": \"Daily Treasury Statement. Provides summary data on the Treasury's cash and debt operations for the Federal Government. Published each Federal working day. Subscription price: $204 per year (domestic), $255 per year (foreign).\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [111, 690, 958, 840], \"page_id\": 2}], \"content\": \"Monthly Treasury Statement of Receipts and Outlays of the United States Government. Provides Federal budget results, including receipts and outlays of funds, the surplus or deficit, and the means of financing the deficit or disposing of the surplus. Preparation based on agency reporting. Subscription price: $27 per year (domestic), $33.75 per year (foreign).\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [116, 856, 934, 952], \"page_id\": 2}], \"content\": \"Consolidated Financial Statements of the United States Government (annual). Provides information about Government financial operations on the accrual basis. Single copy price: $2.25.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [112, 976, 976, 1089], \"page_id\": 2}], \"content\": \"United States Government Annual Report and Appendix. Annual Report presents budgetary results at the summary level. Appendix presents the individual receipt and appropriation accounts at the detail level. Annual Report single copy price: $2; Appendix free from Financial Management Service.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 1187, 575, 1217], \"page_id\": 2}], \"content\": \"+ Subscription order form on inside back cover of this issue\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [42, 1349, 452, 1368], \"page_id\": 2}], \"content\": \"ON THE COVER: A line drawing from an old photograph of\", \"description\": null, \"id\": 7, \"type\": \"page_foote