"page_number\"}, {\"bbox\": [{\"coord\": [260, 160, 909, 184], \"page_id\": 109}], \"content\": \"INTRODUCTION: International Financial Statistics\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [80, 218, 570, 269], \"page_id\": 109}], \"content\": \"The tables in this section provide statistics on the U.S. Government's reserve assets, liabilities to foreigners, and its international financial position.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [80, 290, 570, 375], \"page_id\": 109}], \"content\": \"Table IFS-1 shows reserve assets of the United States, including gold stock and special drawing rights held in the Special Drawing Account in the International Monetary Fund (IMF). The table also shows U.S. reserve holdings and holdings of convertible foreign currencies in the IMF.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [80, 393, 572, 445], \"page_id\": 109}], \"content\": \"Table IFS-2 contains statistics on liabilities to foreign official institutions, and selected liabilities to all other foreigners, which are used in the United States balance of payments statistics.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [596, 220, 1082, 267], \"page_id\": 109}], \"content\": \"Table IFS-3 shows nonmarketable bonds and notes that Treasury issues to official institutions and other residents of foreign countries. The figures are in dollars or dollar equivalents.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [596, 290, 1082, 426], \"page_id\": 109}], \"content\": \"Table IFS-4 presents the general foreign exchange value of the U.S. dollar. Values presented are broader than those provided by single exchange rate levels and do not claim to represent a guide to measuring the impact of exchange rate levels on United States international transactions. Indices are computed as geometric averages of individual currency levels with weights derived from the share of each country's trade with the United States during the years 1982 and 1983.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [25, 54, 59, 74], \"page_id\": 110}], \"content\": \"100\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [331, 79, 733, 98], \"page_id\": 110}], \"content\": \"INTERNATIONAL FINANCIAL STATISTICS\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [347, 176, 718, 196], \"page_id\": 110}], \"content\": \"TABLE IFS-1.--U.S. Reserve Assets\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [471, 216, 586, 230], \"page_id\": 110}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [18, 232, 1043, 585], \"page_id\": 110}], \"content\": \"<table><tr><th>End of calendar year or month</th><th>Total reserve assets 1</th><th>Gold stock 2</th><th>Special drawing rights 3</th><th>Foreign currencies 4</th><th>Reserve position in International Monetary Fund 1 5</th></tr><tr><td>1987</td><td>45,798</td><td>11,078</td><td>10,283</td><td>13,088</td><td>11,349</td></tr><tr><td>1988</td><td>47,802</td><td>11,057</td><td>9,637</td><td>17,363</td><td>9,745</td></tr><tr><td>1989</td><td>74,609</td><td>11,059</td><td>9,351</td><td>44,551</td><td>9,048</td></tr><tr><td>1990</td><td>83,316</td><td>11,058</td><td>10,989</td><td>52,193</td><td>9,076</td></tr><tr><td>1991 - Jan</td><td>85,006</td><td>11,058</td><td>10,922</td><td>53,558</td><td>9,468</td></tr><tr><td>Feb</td><td>82,797</td><td>11,058</td><td>10,958</td><td>51,225</td><td>9,556</td></tr><tr><td>Mar</td><td>78,002</td><td>11,058</td><td>10,368</td><td>47,666</td><td>8,910</td></tr><tr><td>Apr</td><td>78,297</td><td>11,058</td><td>10,325</td><td>48,108</td><td>8,806</td></tr><tr><td>May</td><td>78,263</td><td>11,057</td><t