ord\": [131, 708, 988, 1231], \"page_id\": 150}], \"content\": null, \"description\": null, \"id\": 9, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1046, 41, 1083, 70], \"page_id\": 151}], \"content\": \"141\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [459, 61, 699, 90], \"page_id\": 151}], \"content\": \"TRUST FUND REPORTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [324, 158, 828, 196], \"page_id\": 151}], \"content\": \"INTRODUCTION: Asbestos Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [64, 206, 565, 363], \"page_id\": 151}], \"content\": \"The asbestos trust fund was established on the books of the Treasury in fiscal 1987 according to Public Law 99-519, October 22, 1986. It consists of amounts received in the Treasury on or after January 1, 1987, as repayments of loans made under section 505 of the Asbestos School Hazard Abatement Act of 1984 (20 U.S.C. 4011 et seq.), and amounts received as deposits from local educational agencies (LEAs) under section 207(a) of the Toxic Substances Control Act.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [61, 363, 564, 451], \"page_id\": 151}], \"content\": \"Amounts available in the fund exceeding current outlay requirements have been invested in interest-bearing obligations of the United States, and any interest earned and proceeds from sale or redemption have been credited to the fund. Beginning in fiscal 1992,\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [589, 209, 1090, 293], \"page_id\": 151}], \"content\": \"the Credit Reform Act of 1990 requires that all interest earned, repayments, and civil penalties collected from LEAs for loans made prior to fiscal 1992, be deposited into a liquidating account that will then be deposited into a miscellaneous receipts account at Treasury.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [589, 290, 1083, 351], \"page_id\": 151}], \"content\": \"Repayments collected for loans made in fiscal 1992 and fiscal years thereafter will be directly deposited into the miscellaneous receipts account.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [592, 349, 1090, 427], \"page_id\": 151}], \"content\": \"Annual reports to the Congress are required of the Secretary of the Treasury each year on the financial condition and results of the operations of the trust fund for the preceding fiscal year and on its expected condition and operations during the next 5 fiscal years.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [373, 560, 776, 622], \"page_id\": 151}], \"content\": \"TABLE TF-11.--Asbestos Trust Fund Results of Operations, Fiscal 1991\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [445, 627, 700, 656], \"page_id\": 151}], \"content\": \"(Source: Financial Management Service)\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [61, 654, 1093, 823], \"page_id\": 151}], \"content\": \"<table><tr><td>Balance Oct. 1, 1990</td><td>$14,866,814</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Loan repayments</td><td>6,761,000</td></tr><tr><td>Penalties</td><td>6,000</td></tr><tr><td>Interest on investments</td><td>1,236,848</td></tr><tr><td>Interest on investments-accrued</td><td>113,880</td></tr><tr><td>Total receipts</td><td>8,119,728</td></tr><tr><td>Balance Sept. 30, 1991</td><td>22,986,541</td></tr></table>\", \"description\": null, \"id\": 10, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [215, 863, 933, 901], \"page_id\": 151}], \"content\": \"Expected Condition and Results of Operations, Fiscal Years 1992-96\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [494, 898, 649, 925], \"page_id\": 151}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [59, 921, 1088, 1148], \"page_id\": 151}], \"content\": \"<table><tr><th></th><th>1992</th><th>1993</th><th>1994</th><th>1995</th><th>1996</th></tr><tr><td>Balance Oct. 1<sup>1</sup></td><td>22.9</td><td>37.7</td><td>49.2</td><td>60.7</td><td>72.2</td></tr><tr><td>Receipts:</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Loan repayments</td><td>10.1</td><td>11.5</td><td>11.5</td><td>11.5</td><td>11.5</td></tr><tr><td>Fines and penalties</td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Interest on investments</td><td>4.7</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Total receipts</td><td>14.8</td><td>11.5</td><td>11.5</td><td>11.5</td><td>11.5</td></tr><tr><td>Outlays</td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Balance Sept. 30<sup>1</sup></td><td>37.7</td><td>49.2</td><td>60.7</td><td>72.2</td><td>83.7</td></tr></table>\", \"description\": null, \"id\": 13, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [63, 1168, 563, 1208], \"page_id\": 151}], \"content\": \"1 Includes unrealized discounts on investments as represented in the Budget of the United States Government, Fiscal Year 1993.\", \"description\": null, \"id\": 14, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [24, 37, 71, 66], \"page_id\": 152}], \"content\": \"142\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [415, 61, 653, 88], \"page_id\": 152}], \"content\": \"TRUST FUND REPORTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [212, 164, 859, 196], \"page_id\": 152}], \"content\": \"INTRODUCTION: Black Lung Disability Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [20, 215, 526, 333], \"page_id\": 152}], \"content\": \"The black lung disability trust fund was established on the books of the Treasury in fiscal 1978 according to the Black Lung Benefits Revenue Act of 1977. Public Law 97-119, December 29, 1981, entitled \\\"Trust Fund Code of 1981\\\" (26 U.S.C. 9501), provides for the continuation of the fund as previously established under section 3 of the act of 1977.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [18, 343, 520, 429], \"page_id\": 152}], \"content\": \"The Consolidated Omnibus Budget Reconciliation Act of 1985 (Public Law 99-272), enacted April 7, 1986, provided for an increase in the coal tax effective April 1, 1986, through December 31, 1995, and a 5-year forgiveness of interest retroactive to October 1, 1985.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [20, 445, 524, 548], \"page_id\": 152}], \"content\": \"The 5-year moratorium on interest payments ended on September 30, 1990. Payment of interest on advances resumed in fiscal 1991. The Omnibus Budget Reconciliation Act of 1987 (Public Law 100-203), signed December 22, 1987, extends the temporary increase in the coal tax through December 31, 2013.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [23, 566, 521, 666], \"page_id\": 152}], \"content\": \"The Act designates the following receipts to be appropriated and transferred from the general fund of the Treasury to the trust fund: excise taxes on mined coal tonnage; taxable expenditures of private black lung benefit trusts; reimbursements by responsible mine operators; and related fines, penalties, and interest charges.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [548, 206, 1051, 274], \"page_id\": 152}], \"content\": \"Estimates made by the Secretary of the Treasury determine monthly transfers of amounts for excise taxes to the trust fund, subject to adjustments in later transfers to actual tax receipts.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [544, 284, 1050, 409], \"page_id\": 152}], \"content\": \"After retirement of the current indebtedness, amounts available in the fund exceeding current expenditure requirements will be invested by the Secretary of the Treasury in interest-bearing public debt securities. Any interest earned is credited to the fund. Also credited, if necessary, are repayable advances from the general fund to meet outlay requirements exceeding available revenues.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [552, 421, 1051, 529], \"page_id\": 152}], \"content\": \"To carry out the program, amounts are made available to the Department of Labor. Other charges to the fund are to pay administrative expenses incurred by the Department of Health and Human Services and the Department of the Treasury, and also to repay advances from the general fund and interest on advances.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [550, 541, 1046, 666], \"page_id\": 152}], \"content\": \"The act requires the Secretary of the Treasury to submit an annual report to Congress after consultation with the Secretary of Labor and the Secretary of Health and Human Services (26 U.S.C. 9602 (a)). The report must present the financial condition and results of operations of the fund during the past fiscal year and the expected condition and operations of the fund during the next 5 fiscal years.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [270, 722, 802, 783], \"page_id\": 152}], \"content\": \"TABLE TF-12.--Black Lung Disability Trust Fund Results of Operations, Fiscal 1991\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [428, 788, 646, 815], \"page_id\": 152}], \"content\": \"(Source: Financial Management Service)\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [24, 815, 1041, 1229], \"page_id\": 152}], \"content\": \"<table><tr><td>Balance 