\"content\": \"TRUST FUND REPORTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [202, 171, 846, 194], \"page_id\": 154}], \"content\": \"INTRODUCTION: Harbor Maintenance Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [14, 222, 507, 298], \"page_id\": 154}], \"content\": \"The harbor maintenance trust fund was established on the books of the Treasury on April 1, 1987, according to the Water Resources Development Act of 1986 (Public Law 99-962, November 17, 1986) (26 U.S.C. 9505).\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [13, 298, 506, 435], \"page_id\": 154}], \"content\": \"The harbor maintenance trust fund consists of such amounts as may be appropriated provided by section 9505(b), transferred by the Saint Lawrence Seaway Development Corporation (SLSDC) according to section 13(a) of the Act of May 13, 1954, or credited as provided in section 9602(b). Amounts are appropriated equivalent to the taxes received in the Treasury under section 4461 (relating to harbor maintenance tax).\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [16, 435, 510, 646], \"page_id\": 154}], \"content\": \"Amounts in the harbor maintenance trust fund are available as provided by appropriation acts for making expenditures to carry out section 210(a) of the Water Resources Development Act of 1986, for payments of rebates of tolls or charges according to section 13(b) of the Act of May 13, 1954 (as in effect on April 1, 1987), and for the payment of all expenses of administration incurred by the Department of the Treasury in administering subchapter A of chapter 36 (relating to harbor maintenance tax), but not exceeding $5 million for any fiscal year and for periods during which no fee applies under paragraph (9) or (10) of section 1303(1(a) of the Consolidated Omnibus Budget Reconciliation Act of 1985.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 649, 512, 666], \"page_id\": 154}], \"content\": \"The provision in the act for payment of the expenses of the\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [540, 220, 1035, 333], \"page_id\": 154}], \"content\": \"administration costs from this source has been found to be in violation of the General Agreement on Tariffs and Trade (GATT). Therefore, legislation has been proposed to authorize payment from the trust fund itself of expenses up to $5 million annually to the Department of the Army for administration costs of the Army, the Department of Commerce, and Treasury.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [541, 333, 1035, 531], \"page_id\": 154}], \"content\": \"The harbor maintenance user fee was increased by the Omnibus Budget Reconciliation Act of 1990 (Public Law 101-508, approved November 5, 1990). The ad valorem user fee imposed on applicable commercial cargo increased from 0.04 percent to 0.125 percent. The Water Resources Development Act of 1990 increased to 100 percent the amount of the harbor maintenance costs that can be financed by the trust fund. Legislation is also being proposed in fiscal 1992 to authorize payment of $45.5 million to the National Oceanic and Atmospheric Administration (NOAA), which was included in calculating the 0.125 percent ad valorem rate.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [536, 529, 1035, 627], \"page_id\": 154}], \"content\": \"Annual reports to Congress are required by 26 U.S.C. 9505 to be submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and the results of operations of the fund during the past fiscal year and its expected condition and operations during the next 5 fiscal years.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [265, 742, 787, 803], \"page_id\": 154}], \"content\": \"TABLE TF-13.--Harbor Maintenance Trust Fund Results of Operations, Fiscal 1991\", \"description\": null, \"id\": 10, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [407, 813, 628, 834], \"page_id\": 154}], \"content\": \"(Source: Financial Management Service)\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [13, 834, 1012, 1113], \"page_id\": 154}], \"content\": \"<table><tr><td>Balance Oct. 1, 1990</td><td>$30,253,588</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Excise taxes:</td><td></td></tr><tr><td>Imports</td><td>217,002,000</td></tr><tr><td>Exports</td><td>90,646,000</td></tr><tr><td>Domestic</td><td>52,460,000</td></tr><tr><td>Zones and missions</td><td>14,312,000</td></tr><tr><td>Toll receipts</td><td>9,266,628</td></tr><tr><td>Interest on investments</td><td>11,696,942</td></tr><tr><td>Interest income discount</td><td>117,411</td></tr><tr><td>Total receipts</td><td>395,500,981</td></tr><tr><td>Expenses:</td><td></td></tr><tr><td>Corps of Engineers</td><td>333,401,552</td></tr><tr><td>SLSDC</td><td>9,075,000</td></tr><tr><td>Toll rebates</td><td>10,484,089</td></tr><tr><td>Total expenses</td><td>352,960,641</td></tr><tr><td>Balance Sept. 30, 1991</td><td>72,793,928</td></tr></table>\", \"description\": null, \"id\": 12, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [1038, 63, 1082, 90], \"page_id\": 155}], \"content\": \"145\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [465, 85, 698, 111], \"page_id\": 155}], \"content\": \"TRUST FUND REPORTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [213, 181, 941, 247], \"page_id\": 155}], \"content\": \"TABLE TF-13.--Harbor Maintenance Trust Fund, Con. Expected Condition and Results of Operations, Fiscal Years 1992-96\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [545, 250, 671, 271], \"page_id\": 155}], \"con