scription\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [71, 311, 720, 413], \"page_id\": 130}], \"content\": \"Worldwide net positions on the last business day of the calendar quarter of nonbanking business concerns in the United States, their foreign branches and majority-owned partnerships and subsidiaries. Excludes receivables and installment paper that have been sold or discounted before maturity, U.S. parent companies' investments in their majority-owned foreign subsidiaries, fixed assets (plant and equipment), and capitalized leases for plant and equipment\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [70, 424, 571, 437], \"page_id\": 130}], \"content\": \"Foreign branches, majority-owned partnerships, and subsidiaries only\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [71, 448, 720, 499], \"page_id\": 130}], \"content\": \"Weekly worldwide net positions of banks and banking institutions in the United States, their foreign branches, and majority-owned foreign subsidiaries. Excludes capital assets and liabilities\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [71, 508, 473, 523], \"page_id\": 130}], \"content\": \"Foreign branches and majority-owned subsidiaries only\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [70, 561, 348, 579], \"page_id\": 130}], \"content\": \"SECTIONS II THROUGH VII\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [71, 585, 720, 638], \"page_id\": 130}], \"content\": \"1 Positions of nonbanking business concerns in the United States, their foreign branches, majority-owned partnerships, and subsidiaries. In section VII, positions of foreign branches, majority-owned partnerships, and subsidiaries only.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [765, 276, 1413, 314], \"page_id\": 130}], \"content\": \"2 Excludes receivables and installment paper sold or discounted before maturity, fixed assets (plant and equipment), and parents' investment in majority-owned foreign subsidiaries\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 320, 1148, 338], \"page_id\": 130}], \"content\": \"Capitalized plant and equipment leases are excluded.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 345, 1105, 360], \"page_id\": 130}], \"content\": \"Includes both spot and forward exchange rates\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 371, 1050, 384], \"page_id\": 130}], \"content\": \"5 Columns 1 and 3 less columns 2 and 4\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [765, 393, 1415, 446], \"page_id\": 130}], \"content\": \"Representative rates on the report date. Canadian dollar and United Kingdom pound rates are expressed in U.S. dollars per unit of foreign currency, all others in foreign units per U.S. dollar. The source of the automated representative rates changed as of June 30, 1988.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 455, 1413, 488], \"page_id\": 130}], \"content\": \"Banks and banking institutions in the United States, their foreign branches, and majority-owned subsidiaries. In section VII, foreign branches and majority-owned subsidiaries only.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 495, 942, 512], \"page_id\": 130}], \"content\": \"Excludes capital assets\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 523, 955, 539], \"page_id\": 130}], \"content\": \"Excludes capital liabilities\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 548, 1141, 565], \"page_id\": 130}], \"content\": \"Includes both spot and forward exchange contracts\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 574, 1065, 590], \"page_id\": 130}], \"content\": \"Columns 3 and 9 less columns 6 and 12\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [766, 599, 886, 616], \"page_id\": 130}], \"content\": \"12 See footnote 6\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [539, 49, 988, 78], \"page_id\": 131}], \"content\": \"EXCHANGE STABILIZATION FUND\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1378, 38, 1440, 85], \"page_id\": 131}], \"content\": \"121\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [378, 237, 1146, 288], \"page_id\": 131}], \"content\": \"INTRODUCTION: Exchange Stabilization Fund\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [81, 322, 750, 456], \"page_id\": 131}], \"content\": \"To stabilize the exchange value of the dollar, the Exchange Stabilization Fund (ESF) was established under the Gold Reserve Act of January 30, 1934 (31 U.S.C. 822a), which authorized establishment of a Treasury Department fund to be operated under the exclusive control of the Secretary, with approval of the President.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [86, 463, 755, 543], \"page_id\": 131}], \"content\": \"Subsequent amendment of the Gold Reserve Act modified the original purpose somewhat to reflect termination of the fixed exchange rate system.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [88, 548, 751, 673], \"page_id\": 131}], \"content\": \"Resources of the fund include dollar balances, partially invested in U.S. Government securities, Special drawing rights (SDRs), and balances of foreign currencies. Principal sources of income (losses) for the fund are profits (losses) on SDRs and foreign exchange, as well as interest earned on assets.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [781, 331, 1443, 525], \"page_id\": 131}], \"content\": \"Table ESF-1 presents the assets, liabilities, and capital of the fund. The figures are in U.S. dollars or their equivalents based on current exchange rates computed according to the accrual method of accounting. The capital account represents the original capital appropriated to the fund by Congress of $2 billion, minus a subsequent transfer of $1.8 billion to pay for the initial U.S. quota subscription to the IMF. Gains and losses are reflected in the cumulative net income (loss) account.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [783, 539, 1451, 693], \"page_id\": 131}], \"content\": \"Table ESF-2 shows the results of operations by quarter. Figures are in U.S. dollars or their equivalents computed according to the accrual method. \\\"Profit (loss) on foreign exchange\\\" includes realized profits or losses on currencies held. \\\"Adjustment for change in valuation of SDR holdings and allocations\\\" reflects net gain or loss on revaluation of SDR holdings and allocations for the quarter.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [65, 35, 111, 60], \"page_id\": 132}], \"content\": \"122\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [516, 35, 954, 60], \"page_id\": 132}], \"content\": \"EXCHANGE STABILIZATION FUND\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [299, 239, 1166, 269], \"page_id\": 132}], \"content\": \"TABLE ESF-1.--Balances as of June 30, 1992, and Sept. 30, 1992\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [481, 296, 985, 316], \"page_id\": 132}], \"content\": \"(In thousands of dollars. Source: Office of the Secretary of the Treasury)\", \"description\": null, \"id\": 