\": [{\"coord\": [61, 1343, 688, 1418], \"page_id\": 41}], \"content\": \"* Less than $500,000. 1 Includes reports for Library of Congress, Government Printing Office, and General Accounting Office. 2 No reports received from this entity.\", \"description\": null, \"id\": 5, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [59, 54, 87, 85], \"page_id\": 42}], \"content\": \"28\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [621, 116, 939, 149], \"page_id\": 42}], \"content\": \"FEDERAL OBLIGATIONS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [407, 319, 1400, 361], \"page_id\": 42}], \"content\": \"GROSS FEDERAL OBLIGATIONS AS OF SEPT. 30, 1990\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [104, 442, 1454, 1015], \"page_id\": 42}], \"content\": null, \"description\": null, \"id\": 3, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [294, 1086, 1253, 1849], \"page_id\": 42}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1388, 53, 1418, 75], \"page_id\": 43}], \"content\": \"29\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [519, 121, 972, 141], \"page_id\": 43}], \"content\": \"ACCOUNT OF THE U.S. TREASURY\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [277, 186, 1219, 210], \"page_id\": 43}], \"content\": \"SOURCE AND AVAILABILITY OF THE BALANCE IN THE ACCOUNT OF THE U.S. TREASURY\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [68, 265, 728, 501], \"page_id\": 43}], \"content\": \"The operating cash of the Treasury is maintained in Treasury's accounts with the Federal Reserve banks and branches and in tax and loan accounts. Major information sources include the Daily Balance Wire received from the Federal Reserve banks and branches, and electronic transfers through the Letter of Credit Payment, Fedline Payment, and Fedwire Deposit Systems. As the balances in the accounts at the Federal Reserve banks become depleted, they are restored by calling in (withdrawing) funds from thousands of financial institutions throughout the country authorized to maintain tax and loan accounts.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [68, 528, 723, 766], \"page_id\": 43}], \"content\": \"Under authority of Public Law 95-147, the Treasury implemented a program on Nov. 2, 1978, to invest a portion of its operating cash in obligations of depositaries maintaining tax and loan accounts. Under the Treasury tax and loan investment program, depository financial institutions select the manner in which they will participate in the program. Depositaries that wish to retain funds deposited in their tax and loan accounts in interest-bearing obligations participate under the Note Option; depositaries that wish to remit the funds to the Treasury's account at Federal Reserve banks participate under the Remittance Option.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [768, 265, 1425, 546], \"page_id\": 43}], \"content\": \"business under a uniform procedure applicable to all financial institutions whereby customers of financial institutions deposit with them tax payments and funds for the purchase of Government securities. In most cases the transaction involves merely the transfer of funds from a customer's account to the tax and loan account in the same financial institution. On occasion, to the extent authorized by the Treasury, financial institutions are permitted to deposit in these accounts proceeds from subscriptions to public debt securities entered for their own account as well as for the accounts of their customers. Also, Treasury can direct the Federal Reserve banks to invest excess funds in these accounts directly from its account at the Federal Reserve banks.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [758, 574, 1416, 742], \"page_id\": 43}], \"content\": \"The tax and loan system permits the Treasury to collect funds through financial institutions and to leave the funds in Note Option depositaries and in the financial communities in which they arise until such time as the Treasury needs the funds for its operations. In this way the Treasury is able to neutralize the effect of its fluctuating operations on Note Option financial institution reserves and the economy.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [103, 791, 721, 819], \"page_id\": 43}], \"content\": \"Deposits to tax and loan accounts occur in the normal course of\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [111, 857, 1363, 888], \"page_id\": 43}], \"content\": \"Table UST-1.--Elements of Changes in Federal Reserve and Tax and Loan Note Account Balances\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [539, 899, 982, 923], \"page_id\": 43}], \"content\": \"(In millions of dollars. Source: Financial Management Service)\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [63, 925, 1413, 1491], \"page_id\": 43}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Fiscal year or month</th><th colspan=\\\"3\\\">Federal Reserve accounts</th><th colspan=\\\"5\\\">Credits and withdrawals</th></tr><tr><th colspan=\\\"2\\\">Credits 1</th><th rowspan=\\\"2\\\">Withdrawals 2</th><th colspan=\\\"2\\\">Proceeds from sales of securities 3</th><th colspan=\\\"2\\\">Tax and loan note accounts</th><th rowspan=\\\"2\\\">Withdrawals (transfers to Federal Reserve accounts)</th></tr><tr><th>Received directly</th><th>Received through remittance option tax and loan depositories</th><th>Marketable issues</th><th>Nonmarketable issues 4</th><th>Taxes 5</th><th>Total credits</th></tr><tr><td>1986</td><td>2,174,675</td><t