ox\": [{\"coord\": [643, 117, 864, 148], \"page_id\": 75}], \"content\": \"MARKET YIELDS\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [660, 186, 854, 212], \"page_id\": 75}], \"content\": \"INTRODUCTION\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [778, 267, 1435, 389], \"page_id\": 75}], \"content\": \"a consistent data series. Yields on Treasury bills, which are discount securities, are the coupon equivalent yields of bank discount rates at which Treasury bills trade in the market. The Board of Governors of the Federal Reserve System also publishes the Treasury constant maturity data series in its weekly H.15 press release.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [779, 428, 1428, 479], \"page_id\": 75}], \"content\": \"Table MY-2.--Average Yields of Long-Term Treasury, Corporate, and Municipal Bonds\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [779, 501, 1431, 623], \"page_id\": 75}], \"content\": \"The long-term Treasury rate is the 30-year constant maturity rate presented in table MY-1. The corporate and municipal bond series are developed by the Treasury, using reoffering yields on new long-term securities rated Aa by Moody's Investors Service. See the footnotes for further explanation.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [52, 58, 84, 85], \"page_id\": 76}], \"content\": \"62\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [616, 91, 833, 118], \"page_id\": 76}], \"content\": \"MARKET YIELDS\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [164, 140, 1290, 172], \"page_id\": 76}], \"content\": \"Table MY-1.--Treasury Market Bid Yields at Constant Maturities: Bills, Notes, and Bonds*\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\