pe\": \"text\"}, {\"bbox\": [{\"coord\": [33, 329, 864, 488], \"page_id\": 155}], \"content\": \"<table><tr><td>TRBU SMITH212J</td><td>ISSDUE000</td><td>R</td><td>1</td></tr><tr><td>JOHN SMITH</td><td></td><td></td><td></td></tr><tr><td>212 MAIN ST</td><td></td><td></td><td></td></tr><tr><td>FORESTVILLE MD 20747</td><td></td><td></td><td></td></tr></table>\", \"description\": null, \"id\": 4, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [33, 508, 1386, 579], \"page_id\": 155}], \"content\": \"When that number reads ISSDUE000, you have received your last issue unless you renew. You should receive your renewal notice around the same time that you receive the issue with ISSDUE000 on the top line.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [32, 605, 1386, 705], \"page_id\": 155}], \"content\": \"To be sure that your service continues without interruption, please return your renewal notice promptly. If your subscription service is discontinued, simply send your mailing label from any issue to the Superintendent of Documents, Washington, DC 20402-9372 with the proper remittance, and your service will be reinstated.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [33, 735, 1386, 804], \"page_id\": 155}], \"content\": \"To change your address . . . please SEND YOUR MAILING LABEL, along with your new address, to the Superintendent of Documents, Attn: Chief, Mail List Branch, Mail Stop: SSOM, Washington, DC 20402-9373.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [33, 833, 1386, 899], \"page_id\": 155}], \"content\": \"To inquire about your subscription service ... please SEND YOUR MAILING LABEL, along with your correspondence, to the Superintendent of Documents, Attn: Chief, Mail List Branch, Mail Stop: SSOM, Washington, DC 20402-9375.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [32, 967, 226, 994], \"page_id\": 155}], \"content